"""Safely evaluate Python string literals without using eval()."""

import re

from typing import Dict, Match, Text


simple_escapes: Dict[Text, Text] = {
    "a": "\a",
    "b": "\b",
    "f": "\f",
    "n": "\n",
    "r": "\r",
    "t": "\t",
    "v": "\v",
    "'": "'",
    '"': '"',
    "\\": "\\",
}


